# !! THE OUTPUTS ARE SLIGHTLY DIFFERENT FROM THE PAPER 
#     BECAUSE THE EXAMPLE USES SYNTHETIC DATA (VS NYC DATA IN THE PAPER)

# viral dynamics analysis
# using a synthetic dataset generated by random poisson sampling of NYC data
# 4/24/26

library(tidyverse)
library(data.table)
library(zoo)
library(ggridges)
library(ggh4x)
library(MMWRweek)
library(ggplot2)

setwd(dirname(rstudioapi::getActiveDocumentContext()$path))

dir_out_t = 'outputs_syn_main/'
if (!file.exists(paste0('../',dir_out_t))) {
  dir.create(paste0('../',dir_out_t))
}

# basic settings and utility functions ----
sn_start_wk = 40 # MMWR week of the season start
cut_fullskip = .25 # %reduction cp pre-covid level to be deemed as fully skipping a season
cut_skip = .5
onset_cut_t = .05 # percentage cumulative incidence for finding the onset and ending of epidemic season
end_cut_t = 0.95 # end_cut
tag_base = paste0('_syn','_onsetCI',end_cut_t*100) # file tag

# dates to adjust, March 22 - Oct 2020 for care-seeking behavior, using the same factors for 2020-2021
dates_pdm_adj = seq(as.Date('2020/3/22'), MMWRweek2Date(2020, 39, 7), by = 'day')

if(sn_start_wk == 40){
  years = 2015:2024
} else {
  years = 2016:2024
}

seasons = years |> lapply(function(y){ paste(y,y+1,sep="-")}) |> unlist()
pre_pdm = seasons[which(years<2019)]
post_pdm = seasons[which(years>=2020)] # first one is the pdm - need to check back
pdm = '2019-2020'
pdm_start = '2020/3/1' |> as.Date() # for NYC

# virus names
cols_virus = c("adenovirus", "hmpv","rhino_enterovirus","rsv",
               "corona_nl63","corona_hku", "corona_oc43","corona_229e", "coronavirus", 
               "flu_a", "flu_b", "influenza", 
               "para1","para2","para3", "para4","parainfluenza")
viruses = c("rhino_enterovirus","adenovirus","parainfluenza", "rsv", "coronavirus", "hmpv","influenza")
vnames = c('RV', 'AdV','PIV', 'RSV', 'sCoV', 'HMPV', 'IV')
vnames2 = c('(a) RV', '(b) AdV','(c) PIV', '(d) RSV', '(e) sCoV', '(f) HMPV', '(g) IV')

subviruses = c(paste0("para",1:4), paste0("corona_",c('nl63','229e','oc43','hku')), "flu_a",'flu_b')
subvnames = c(paste0('PIV',1:4), paste0('sCoV: ',c('NL63','229E','OC43','HKU1')), paste0('IV: ',c('A','B')))

# function to find the changes in epid size and timing 
fn_change = function(x, y, wk_date = NULL, wk_id = NULL,
                     cut = cut_skip, cut_full = cut_fullskip, # skip threshold for epid size 
                     onset_cut = onset_cut_t , # percentage cumulative incidence
                     end_cut = end_cut_t  
){
  if(!is.null(wk_date)){ # order by date
    ord = order(wk_date)
    wk_date = wk_date[ord]
    x = x[ord]; y = y[ord]
  }
  
  size = sum(x) # compute the size this season - do it before excluding extra week
  
  
  # THERE IS A MMWR WEEK 53 IN THE SEASON? 
  if(!is.null(wk_id) & any(wk_id == 53)){
    x = head(x, 52); y = head(y[!is.na(y)], 52)
  }
  
  avg_size = sum(y) # do this after excluding extra week, as it is an average for a regular season
  
  # tmp = ccf(x, y, lag.max = 26, plot = F, na.action = na.pass) 
  tmp = ccf(x, y, plot = F)
  # lag.max: Default is 10*log_10(length_ts/num_series), so 14 here
  max_corr = max(tmp$acf)
  best_lag = tmp$lag[which.max(tmp$acf)]
  ipk = which.max(x)
  ion = which(cumsum(x)/sum(x) > onset_cut)[1]
  iend = which(cumsum(x)/sum(x) > end_cut)[1]
  dur = iend - ion 
  peak_wk_diff = ipk-which.max(y)
  onset_wk_diff = ion - which(cumsum(y)/sum(y) > onset_cut)[1]
  if(!is.null(wk_date)){
    onset_wk = wk_date[ion]; peak_wk = wk_date[ipk]; end_wk = wk_date[iend]
  } else {
    onset_wk = ino; peak_wk = ipk; end_wk = iend; 
  }
  
  skip = ifelse(sum(x) / sum(y) < cut, 1, 0)
  fullskip = ifelse(sum(x) / sum(y) < cut_full, 1, 0)
  list(best_lag = best_lag, max_corr = max_corr, 
       peak_wk_diff = peak_wk_diff, onset_wk_diff = onset_wk_diff, 
       epi_peak = peak_wk, epi_start = onset_wk, epi_end = end_wk, epi_dur = dur,
       size = size, avg_size = avg_size, skip = skip, fullskip = fullskip)
}


# data processing ----
# load data
df = read.csv('../data/nyc_resp_syn_data.csv') |>
  mutate(week_start = week_start |> as.Date())
# add season
df = df |> mutate(week = week_start |> MMWRweek() |> pull(MMWRweek),
         year = week_start |> MMWRweek() |> pull(MMWRyear)) |>
  mutate(season = ifelse(week<sn_start_wk,paste(year-1,year,sep="-"),paste(year,year+1,sep="-")))


## first adjust for testing ----
# for pre-pdm weeks, adjust by the seasonal test volume: * tot_s1 / tot_t
# for pdm weeks, adjust on weekly basis
# need to do it in two steps, as we need to adjust all pre-pdm weeks to get the weekly baseline 
df_pre = df |> filter(season %in% pre_pdm) 
n_tests = df_pre |> group_by(season) |>
  reframe(tot_t = sum(total)) |> 
  mutate(tot_s1 = tot_t[season == pre_pdm[1]]) |>
  mutate(f_test = tot_s1 / tot_t)

df_pre = df_pre |> left_join(n_tests, by = 'season') |> setDT()
df_pre = df_pre[, (paste0(cols_virus,'_tadj')) := lapply(.SD, FUN = function(x){x * f_test}), .SDcols = cols_virus]  

# construct the weekly test volume baseline for pdm/post-pdm weeks
# !!!NOTE: no week 53, so those would become NA's
t_wkly_base = df_pre |> select(week, total, f_test) |>
  mutate(total_tadj = total * f_test) |>
  group_by(week) |>
  reframe(t_wk_base = total_tadj |> mean())
# for week 53 - take the average of weeks 52 and 1
t_wkly_base_w53 = t_wkly_base |> filter(week %in% c(52, 1)) |>
  reframe(week = 53, t_wk_base = t_wk_base |> mean())
t_wkly_base_incl53 = rbind(t_wkly_base, t_wkly_base_w53)
# adjust for pdm/post-pdm weeks
df_post = df |> filter(!season %in% pre_pdm) |> 
  left_join(t_wkly_base_incl53, by = 'week') |> setDT()
df_post = df_post[, (paste0(cols_virus,'_tadj')) := lapply(.SD, FUN = function(x){x * t_wk_base / total}), .SDcols = cols_virus]

ck = df_post$adenovirus * df_post$t_wk_base / df_post$total # check results
sum(ck - df_post$adenovirus_tadj, na.rm = T)

# combine both - adjusting for testing
df_tadj = df_pre |> rbind(df_post, fill=T)

## now adjust for medical seeking behavior ----
# using rv as a benchmark
# adjust by assuming rv circulation during post-pdm seasons resumed the pre-pdm mean
rv_sn_tot = df_tadj |> # filter(season %in% pre_pdm) |>
  group_by(season) |> reframe(rv_sn_tot = sum(rhino_enterovirus_tadj, na.rm = T)) 
rv_pre_base = rv_sn_tot |> filter(season %in% pre_pdm) |> pull(rv_sn_tot) |> mean()
rv_madj = rv_sn_tot |> 
  mutate(f_madj = case_when(season %in% c(pre_pdm, pdm) ~ 1, # do not adjust these seasons
                            T ~ rv_pre_base/rv_sn_tot)) |>  
  mutate(f_redn = 1 - 1/f_madj) # reduction cp pre-pdm
# even though we are adjusting the whole season including mmwr week 53, 
# to compute the %redn for 2020-2021, only 52 weeks should be included, otherwise not a fair comparison
# so leave out the last week (w39) for seasons with 53 weeks
rv_madj_noW39 = df_tadj |> filter(!(season=='2020-2021' & week == 39)) |>
  group_by(season) |> reframe(rv_sn_tot = sum(rhino_enterovirus_tadj, na.rm = T)) |> 
  mutate(f_madj = case_when(season %in% c(pre_pdm, pdm) ~ 1, # do not adjust these seasons
                            T ~ rv_pre_base/rv_sn_tot)) |>  
  mutate(f_redn = 1 - 1/f_madj) # reduction cp pre-pdm

df_madj = df_tadj |> left_join(rv_madj, by = 'season') |> setDT()

# ADJUST MARCH 22, 2020 (START OF THE STAY AT HOME ORDER IN NYC) TO END OF THE 2020 SEASON 
# USING THE SAME FACTOR (NO WK39) FOR 2020-2021
df_madj = df_madj |> 
  mutate(f_madj = case_when(week_start %in% dates_pdm_adj ~ rv_madj_noW39 |> filter(season=='2020-2021') |> pull(f_madj), 
                            T ~ f_madj),
         f_redn = case_when(week_start %in% dates_pdm_adj ~ rv_madj_noW39 |> filter(season=='2020-2021') |> pull(f_redn), 
                            T ~ f_redn)) |> setDT()
# now adjust for care-seeking by multiplying f_madj
df_madj = df_madj[, (paste0(cols_virus,'_madj')) := lapply(.SD, FUN = function(x){x * f_madj}), .SDcols = paste0(cols_virus,'_tadj')]

ck = df_madj$influenza_tadj * df_madj$f_madj # check results
sum(ck - df_madj$influenza_madj, na.rm = T)
df_madj |> group_by(season) |> reframe(tot = sum(rhino_enterovirus_madj)) # vs rv_pre_base


## get the pre-pdm wkly average ----
df_cp = copy(df_madj) # make a copy so as not to operate on df_madj
prepdm_avg_l = df_cp[,c('season', 'week', paste0(cols_virus,'_tadj')), with=F] |>
  filter(season %in% pre_pdm) |> 
  pivot_longer(cols = paste0(cols_virus,'_tadj')) |>
  mutate(name = gsub('_tadj','', name)) |>
  group_by(name, week) %>%
  { # baseline mean vs. median
    if(grepl('median', tag_base)){
      reframe(.,value = value |> median()) 
    } else {
      reframe(.,value = value |> mean()) 
    }
  }
  
prepdm_avg = prepdm_avg_l |> pivot_wider()

# combine with the baseline
df_cp = df_cp |> mutate(tot_t=NULL, tot_s1=NULL, f_test=NULL, t_wk_base=NULL, rv_sn_tot=NULL, f_madj=NULL, f_madj2=NULL, total=NULL) |>
  left_join(prepdm_avg, by = 'week', suffix = c('','_avg')) 

epi_baseline = prepdm_avg_l %>% filter(name %in% viruses) %>% mutate(virus = factor(name, levels = viruses, labels = vnames)) %>% group_by(virus) %>% reframe(base = max(value) * .05)


## compute the changes in epid timing and size ----
## for estimates only adjusting for surveillance effort (*_tadj) and estimates adjusting for both surveillance and care-seeking (*_madj)
for(tag_t in c('_tadj','_madj')){
  tda = df_cp[,c('week_start', 'season', 'week', paste0(cols_virus,tag_t)), with=F] |>
    pivot_longer(cols = paste0(cols_virus,tag_t)) |>
    mutate(name = gsub(tag_t,'', name)) |>
    left_join(prepdm_avg_l |> rename(avg = value), by = c('name', 'week')) |>
    # filter(week!=53) |> 
    rename(virus = name) |> 
    # filter(virus %in% viruses) |> mutate(virus = factor(virus, levels = viruses, labels = vnames)) |>
    arrange(virus, week_start)  |> setDT()
  
  epi_change_t = tda[, fn_change(x=value, y=avg, wk_date = week_start, wk_id = week), by = c('virus', 'season')] 
  # construct a range based on stats from pre-pdm seasons
  bounds_t = epi_change_t[season %in% c(pre_pdm,'2019-2020pre'), 
                          list(lag_min = min(best_lag), lag_max = max(best_lag), 
                               pw_min = min(peak_wk_diff), pw_max = max(peak_wk_diff), 
                               on_min = min(onset_wk_diff), on_max = max(onset_wk_diff)),
                          by = c('virus')] 
  epi_change_t = epi_change_t |> left_join(bounds_t, by = c('virus'))
  # get bounds for the epi size pre-pdm
  tmp = epi_change_t |> filter(season %in% pre_pdm) |> group_by(virus) |> reframe(size_min = min(size), size_max = max(size))
  # get cumulative mean post pdm
  tmp2 = epi_change_t |> filter(season %in% c(pdm, post_pdm)) |> group_by(virus) |> 
    arrange(virus, season) |>
    reframe(season = season, cum_avg_size = dplyr::cummean(size))
  epi_change_t = epi_change_t |> left_join(tmp) |> left_join(tmp2) |> 
    mutate(size_predn = ((avg_size - size)/avg_size*100) |> round(2),
           cumsize_predn = ((avg_size - cum_avg_size)/avg_size*100) |> round(2))|> 
    arrange(virus, season)
  
  assign(paste0('epi',tag_t,'_change'), epi_change_t)
}

epi_madj_change_all = epi_madj_change; 
epi_tadj_change_all = epi_tadj_change
epi_madj_change = epi_madj_change_all |> filter(virus %in% viruses) |> mutate(virus = factor(virus, levels = viruses, labels = vnames)) |> arrange(virus) 
epi_tadj_change = epi_tadj_change_all |> filter(virus %in% viruses) |> mutate(virus = factor(virus, levels = viruses, labels = vnames)) |> arrange(virus) 

# save a copy for further analysis
write.csv(epi_madj_change_all, file = paste0('../',dir_out_t,'epi_madj_change_wk',sn_start_wk, tag_base, '.csv'), row.names = F)
write.csv(epi_tadj_change_all, file = paste0('../',dir_out_t,'epi_tadj_change_wk',sn_start_wk, tag_base, '.csv'), row.names = F)
write.csv(epi_madj_change, file=paste0('../',dir_out_t,'tab_epi_madj_change_wk',sn_start_wk, tag_base, '.csv'), row.names = F)
write.csv(epi_tadj_change, file=paste0('../',dir_out_t,'tab_epi_tadj_change_wk',sn_start_wk, tag_base, '.csv'), row.names = F)


