tda1 = df_cp[,c('season', 'week_start',paste0(viruses,'_tadj'), paste0(viruses,'_madj'), paste0(viruses,'_avg')), with=F] |>
  pivot_longer(cols = c(paste0(viruses,'_tadj'), paste0(viruses,'_madj'), paste0(viruses,'_avg'))) |>
  mutate(datatype = case_when(grepl('_tadj', name) ~ 'test-adjusted', 
                              grepl('_madj', name) ~ 'test/care-adjusted',
                              grepl('_avg', name) ~ 'pre-pdm avg'),
         datatype = factor(datatype,levels = c("pre-pdm avg", "test-adjusted","test/care-adjusted"))) |> 
  mutate(name = gsub('_tadj|_madj|_avg','',name),
         value = ifelse(week_start < dates_pdm_adj[1] & datatype=="test/care-adjusted",NA,value)) |> 
  mutate(name = factor(name, levels = viruses, labels = vnames)) 
d_labs = tda1 |> filter(datatype == 'test/care-adjusted' & season %in% c(pdm, post_pdm)) |>
  group_by(name, datatype) |>
  reframe(week_start = min(week_start) + 7, ymax = max(value, na.rm = T))

d_labs2 = tda1 |> filter(datatype == 'test/care-adjusted') |>
  group_by(name) |>
  reframe(week_start = min(week_start) + 7, ymax = max(value, na.rm = T)) |>
  mutate(name2 = factor(name, levels = vnames, labels = vnames2))

