  .[complete.cases(.),]

# for showing weeks with 0 positive samples
tda_i4 = tda_i %>% group_by(virus) %>%
  mutate(i_pos = value >0, i_zero = value==0) %>%
  rowwise() %>% 
  mutate(wk_id = ((week_start - MMWRweek2Date(as.numeric(substr(season,1,4)), 40, 1))/7+1) %>% as.numeric(),
         period = case_when(season %in% pre_pdm ~ 'pre-COVID', T ~ 'pdm/post-pmd')) 
# for showing weeks with incidence > the epi_baseline (5% of mean peak size)
tda_i5 = tda_i |> left_join(epi_baseline, by = 'virus') |> group_by(virus) |>
  mutate(i_level = case_when(value >= base ~ 'above', value < base & value >0 ~ 'below', value==0 ~ 'zero')) |>
  rowwise() |> 
  mutate(wk_id = ((week_start - MMWRweek2Date(as.numeric(substr(season,1,4)), 40, 1))/7+1) |> as.numeric(),
         period = case_when(season %in% pre_pdm ~ 'pre-COVID', T ~ 'pdm/post-pmd')) 

vs1 = head(vnames, 3) # viruses with year-round circulation
vs2 = tail(vnames, 4) # viruses with cold-month circulation
vcols = RColorBrewer::brewer.pal(7, 'Dark2')

# plot all the epi timing together 
cols_cp = RColorBrewer::brewer.pal(n=9, name = 'Set1')
cols_blindok = palette.colors(palette = "Set1") # use colorblind frendly colors
col_t2 = cols_blindok[1] # color
col_t2cp = cols_blindok[2]

pdm_dates = seq(as.Date('2020/3/1'), as.Date('2020/9/26'), by = 'day')
pdm_dates2 = seq(as.Date('2020/3/1'), as.Date('2021/10/02'), by = 'day') # acute phase, 2020 and 2020-2021 season

p2a = tda_i3 |> filter(virus %in% vs1) |>
  ggplot() +
  geom_line(aes(x = wk_id, y = season, alpha = value_rel_in, group=season), col = col_t2, linewidth=1) +
  geom_point(aes(x = wk_peak, y = season), pch = 0, stroke =.1, size = .9) +
  geom_line(aes(x = wk_id, y = season, color = i_zero, group=season), linewidth=1, data = tda_i4 |> filter(virus %in% vs1) |> mutate(i_zero = factor(i_zero, levels = c('TRUE','FALSE')))) +
  geom_text(aes(x = 1, y = Inf, label = virus), color = 'black', data = labs_t |> filter(virus %in% vs1), hjust = 0, vjust = 1.2, size = 2.6) +
  facet_wrap(~virus, ncol = 1) + 
  labs(x = 'MMWR week', y = 'Season', color = '',alpha = 'Relative incidence',  title = '(a) Viruses with year-round transmission') +
  scale_y_discrete(expand = expansion(add = c(.5, 1.3))) +
  scale_x_continuous(breaks = c(seq(1, 52, by = 5), 53), # week adjusted to at MMWR WEEK 40 START
                     labels = c(c(40:52, 1:39)[seq(1, 52, by = 5)], ""), limit = c(1,53), expand = expansion(0, 1)) +
  scale_color_manual(values = c('TRUE' = col_t2cp,'FALSE' = 'transparent'), labels = c("Not detected",''))+
  scale_alpha(limit = c(0.01, 1))+guides(alpha=guide_legend(order=1))+
  theme_bw(base_size = sz_t) + theme_t3 + 
  theme(plot.margin = margin(t = 2, b=10, l = 0, r = 3), legend.title = element_text(size = sz_t-2), legend.text = element_text(size = sz_t-3),
        legend.position = 'bottom', legend.box.margin=margin(-15,-10,-10,-10), legend.key.size = unit(.25, 'cm'))

p2b = tda_i3 |> filter(virus %in% vs2) |>
