      inherit.aes = FALSE, fill = "grey90", alpha = 0.05
    ) +
    geom_vline(xintercept = as.Date(c("2020-3-15","2021-09-12")), linewidth = .2, linetype = 'dashed') +
    annotate("text", x = as.Date("2020-3-15"), y = Inf, label = "school closure", hjust = -.3, vjust = 1.5, size = 2.7) +
    annotate("text", x = as.Date("2020-3-22"), y = Inf, label = "stay-at-home", hjust = 0, vjust = 3.3, size = 2.7) +
    annotate("text", x = as.Date("2021-12-12"), y = Inf, label = "BA.1", hjust = 0, vjust = 1.5, size = 2.7) +
    geom_line(linewidth = 0.3) +
    labs(y = 'Adjusted incidence', x = '', color = '', title = paste0('(',letters[i],') ', gsub(' \\(all\\)','',v_t[1]))) +
    scale_x_date(
      date_breaks = "1 year",
      date_minor_breaks = "1 month",
      date_labels = "%Y",
      expand = expansion(mult = c(0.01, 0.01))
    ) + 
    scale_y_continuous(expand = expansion(mult=0, add = c(0,10)))+
    scale_color_manual(values = c('grey50',head(vcols2,length(v_t)-1)))+
    theme_bw(base_size = sz_t) + theme_t1 + 
    theme(plot.margin = margin(t=1,b=-3,l=5,r=15), legend.position = c(0.1+.05*(length(v_t)-3), 0.94), legend.direction = "horizontal")
  assign(paste0('pS3',letters[i]), pS3_t)
}

pdf(paste0('../',dir_out_t,'figS3',tag_base,'.pdf'), width = 7.5, height = 7.5)
gridExtra::grid.arrange(pS3a, pS3b, pS3c, nrow = 3)
dev.off()

