## Table S1 and S2 ----
# output the estimated epidemic timing ect.
# summary stats for pre-covid seasons: dur mean (range), weeks no positives
tabS1 = epi_madj_change_all |> filter(!season %in% c(pdm, post_pdm) & virus %in% viruses) |> 
  mutate(virus = factor(virus, levels = c(viruses, subviruses), labels = c(vnames, subvnames))) |> 
  group_by(virus) |>
  reframe(`Pre-COVID duration (weeks):\nmean (range)` = paste0(mean(epi_dur), ' (', min(epi_dur),', ', max(epi_dur),')'),
          `Pre-COVID size: mean (range)` = paste0(mean(size) |> round(), ' (', min(size)|> round(),', ', max(size)|> round(),')')) |>
  left_join(tda_i5 |> filter(week_start < pdm_dates[1]) |> group_by(virus) |>
              reframe(`Pre-COVID #weeks with no positive samples` = sum(i_level=='zero'))) |>
  left_join(tda_i5 |> filter(week_start < pdm_dates[1]) |> group_by(virus) |>
              reframe(`Pre-COVID #weeks below` = sum(i_level=='below'))) |>
  left_join(tda_i5 |> filter(week_start %in% pdm_dates | season %in% post_pdm) |> group_by(virus) |>
              reframe(`Post-COVID #weeks with no positive samples` = sum(i_level=='zero'))
  )

writexl::write_xlsx(tabS1, paste0('../',dir_out_t,'TableS1_stats_precovid',tag_base,'.xlsx'))

tabS2 = epi_madj_change_all |> filter(season %in% c(pdm, post_pdm)) |> 
  filter(virus %in% c(viruses,subviruses)) |>
  mutate(virus = factor(virus, levels = c(viruses, subviruses), labels = c(vnames, subvnames))) |>
  mutate(`Epidemic timing:\nonset - end` = paste(epi_start, 'to', epi_end+6),
         `pre-COVID size\nmean (range)` = paste0(round(avg_size,0), ' (', round(size_min,0), ', ', round(size_max, 0),')'),
         cum_avg_size = cum_avg_size |> round(), cumsize_predn = cumsize_predn |> round(2), size = size |> round()
  )  |> 
  select(virus, season, `Epidemic timing:\nonset - end`, epi_dur, best_lag, onset_wk_diff, `pre-COVID size\nmean (range)`, size, cum_avg_size, cumsize_predn) |>
  rename(`duration (weeks)` = epi_dur, `shift (corr)`= best_lag, `shift (onset)` = onset_wk_diff,
         `cum. mean size` = cum_avg_size, `cum. change (%)` = cumsize_predn) |>
  arrange(virus, season)
writexl::write_xlsx(tabS2, paste0('../',dir_out_t,'TableS2_postcovid',tag_base,'.xlsx'))





